head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "options.popupUrl(선택) 파라미터로 options.type 속성값이 'browserPopup' 일때 window.open() 이 열어야 하는 팝업 페이지 자체의 URL 을 설정합니다.",
        "options.popupUrl(선택) 파라미터 생략 시, 기본값 'popup.html' 로 동작합니다.",
        "options.popupName(선택) 파라미터로 팝업 프레임의 상단 표시줄에 표시되는 이름을 설정합니다.",
        "options.popupName(선택) 파라미터는 options.type 속성값이 'browserPopup' 인 경우 document.title 에 설정됩니다.",
        "options.popupName(선택) 파라미터 생략 시, 기본값 'WebSquarePopup' 으로 동작합니다.",
        "'browserPopup' 유형은 브라우저 팝업 차단기에 의해 차단될 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    $c.gcm.createLabel('label="[참고] 실행 시점 = 버튼 클릭 6초 후 는 사용자 클릭 동작 밖에서 window.open 을 실행합니다. (팝업 차단기 동작 확인용, 차단 여부는 브라우저 설정에 따름)"', '', 'label1');

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback, delay) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) setTimeout(callback, delay || 1500);
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



// options.id 로 팝업 정보 조회 (Page Scope 적용 시 실행 ID 는 'mf_' 접두사가 붙음)
scwin.findPopup = function (id) {
    let list = $p.getAllPopupList();
    for (let i = list.length - 1; i >= 0; i--) {
        if ((list[i].options.org_id === id || list[i].options.id === id) && list[i].popupWin) return list[i];
    }
    return null;
};



// options.id 로 팝업 최상위 div 조회
scwin.popupEl = function (id) {
    return document.querySelector(".w2popup_window[id$='" + id + "']");
};



// 팝업 내부 요소(타이틀바 버튼 등) 조회
scwin.popupPart = function (id, suffix) {
    let el = scwin.popupEl(id);
    return el ? document.getElementById(el.id + "_" + suffix) : null;
};



scwin.rectStr = function (el) {
    let r = el.getBoundingClientRect();
    return "left " + Math.round(r.left + window.scrollX) + ", top " + Math.round(r.top + window.scrollY) + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height);
};

scwin.btn_openPopup_onclick = function () {
    let type = par_type.getValue();
    let popupUrl = par_popupUrl.getValue();
    let popupName = par_popupName.getValue();
    let timing = par_timing.getValue();

    let options = { id: "popup_1", type: type, width: "500px", height: "300px" };
    if (popupUrl !== "") options.popupUrl = popupUrl;
    if (popupName !== "") options.popupName = popupName;

    if (timing === "delay") {
        // 사용자 클릭 동작 유효 시간(약 5초) 밖인 6초 후에 window.open 실행
        setTimeout(function () {
            scwin.runOpenPopup([options], scwin.printResult, 2000);
        }, 6000);
    } else {
        scwin.runOpenPopup([options], scwin.printResult, 2000);
    }
};



// validation 1~6 판정 출력 (browserPopup : 주소·document.title / wframePopup : 상단 표시줄 이름·표시 여부·브라우저 창 수)
scwin.printResult = function () {
    let pw = scwin.findPopup("popup_1");
    let type = par_type.getValue();
    if (type === "browserPopup") {
        if (!pw) {
            scwin.out("window.open 결과 : 차단됨");
            return;
        }
        let url = "", title = "";
        try {
            url = pw.popupWin.location.pathname + pw.popupWin.location.search;
            title = pw.popupWin.document.title;
        } catch (e) {}
        scwin.out("window.open 결과 : 열림 / 주소 : " + url + " / document.title : " + title);
    } else {
        // wframePopup : 상단 표시줄 이름 / 화면 표시 여부 / 새 브라우저 창이 열리지 않았는지(열려 있는 browserPopup 창 수)
        let el = scwin.popupEl("popup_1");
        let titleEl = scwin.popupPart("popup_1", "header_title");
        let winCount = $p.getAllPopupList().filter(function (p) {
            let w = p.popupWin;
            try { return !!w && w.window === w && !w.closed; } catch (e) { return false; }
        }).length;
        scwin.out("상단 표시줄 이름 : " + (titleEl ? titleEl.textContent : "없음") + " / 팝업 표시 : " + (!!el && el.offsetWidth > 0) + " / 열린 브라우저 창 수 : " + winCount);
    }
};
